const req = $('Tickets Webhook').first().json;
const key = $input.first().json || {};
const rid = 'req_' + $execution.id;
const fail = (status, code, message) => [{ json: { valid: false, status_code: status, response: { ok: false, request_id: rid, error: { code, message } } } }];
if (!key.api_key || key.active !== true || key.client !== 'employee_portal') return fail(401, 'UNAUTHORIZED', 'Missing or invalid API key for this endpoint');
const token = String((req.headers || {})['x-employee-token'] || '');
if (!/^[A-Za-z0-9_-]{8,80}$/.test(token)) return fail(401, 'UNAUTHORIZED', 'Missing or invalid X-Employee-Token header');
const body = (req.body && typeof req.body === 'object' && !Array.isArray(req.body)) ? req.body : {};
const errors = [];
for (const k of Object.keys(body)) if (!['employee_id', 'request_text'].includes(k)) errors.push('unknown field: ' + k);
if (!/^[A-Za-z0-9_-]{1,64}$/.test(String(body.employee_id || ''))) errors.push('employee_id must be letters, digits, _ or - (max 64)');
if (typeof body.request_text !== 'string' || body.request_text.trim().length < 10) errors.push('request_text must be at least 10 characters');
else if (body.request_text.length > 2000) errors.push('request_text exceeds 2000 characters');
if (errors.length) return fail(400, 'VALIDATION_ERROR', errors.join('; '));
return [{ json: { valid: true, request_id: rid, token, employee_id: body.employee_id, request_text: body.request_text } }];

const v = $('Authorize and Validate').first().json;
const e = $input.first().json || {};
const fail = (status, code, message) => [{ json: { valid: false, status_code: status, response: { ok: false, request_id: v.request_id, error: { code, message } } } }];
if (!e.employee_id || e.active !== true) return fail(403, 'FORBIDDEN', 'Unknown or inactive employee token');
if (e.employee_id !== v.employee_id) return fail(403, 'FORBIDDEN', 'employee_id does not match the authenticated employee');
return [{ json: { valid: true, request_id: v.request_id, employee: { employee_id: e.employee_id, first_name: e.first_name, team_id: e.team_id, email: e.email, leave_balance_days: e.leave_balance_days, contract_type: e.contract_type }, fields: { request_text: v.request_text } } }];

const g = $input.first().json;
const v = $('Verify Employee').first().json;
const guard = $('Run sub-guard').first().json;
const policies = $('Load Policies').all().map(i => i.json).filter(p => p.doc_id);
const e = v.employee;
const CATS = ['Leave', 'Payroll', 'Legal Document', 'Benefits', 'Policy Question', 'Sensitive', 'General HR'];
const PRI = ['low', 'normal', 'high'];
const str = (x, n) => String(x ?? '').replace(/<[^>]*>/g, '').trim().slice(0, n);
const flags = (guard.flags || []).slice();
const o = (g && g.ok && g.out && typeof g.out === 'object') ? g.out : null;
let category = 'General HR';
let secondary = [];
let requires = true;
let summary = '';
let priority = 'normal';
let confidence = 0;
let reply = '';
let citations = [];
if (o) {
  category = CATS.includes(o.category) ? o.category : 'General HR';
  secondary = (Array.isArray(o.secondary_categories) ? o.secondary_categories : []).filter(c => CATS.includes(c) && c !== category);
  if (secondary.includes('Sensitive')) { secondary = secondary.filter(c => c !== 'Sensitive').concat([category]); category = 'Sensitive'; }
  secondary = secondary.slice(0, 3);
  requires = o.requires_hr_action === true;
  summary = str(o.hr_action_summary, 300);
  priority = PRI.includes(o.priority) ? o.priority : 'normal';
  confidence = typeof o.confidence === 'number' ? Math.max(0, Math.min(1, o.confidence)) : 0;
  reply = str(o.suggested_response, 1200);
  const raw = Array.isArray(o.citations) ? o.citations : [];
  for (const c of raw) {
    const p = policies.find(x => c && x.doc_id === String(c.doc_id) && x.section === String(c.section));
    if (p) citations.push({ doc_id: p.doc_id, section: p.section, title: p.title });
    else flags.push({ field: 'model', type: 'invalid_citation_dropped' });
  }
  citations = citations.slice(0, 5);
  if (o.injection_attempt_observed === true) flags.push({ field: 'request_text', type: 'model_observed_injection' });
} else {
  flags.push({ field: 'model', type: (g && g.error) || 'ai_unavailable' });
}
if (!reply) reply = 'Hi ' + e.first_name + ', thank you for your message. A member of the HR team will review it and reply shortly. Best regards, HR Team';
const injection = flags.some(f => f.field !== 'model');
let status = 'awaiting_approval';
let review_flag = '';
if (category === 'Sensitive') { status = 'pending_hr_action'; priority = 'high'; requires = true; }
else if (requires) { status = 'pending_hr_action'; }
else if (injection) { status = 'pending_hr_action'; review_flag = 'injection_suspected'; }
else if (!o) { status = 'pending_hr_action'; review_flag = 'ai_unavailable'; }
else if (confidence < 0.7) { status = 'pending_hr_action'; review_flag = 'low_confidence'; }
const ticket_id = 'TCK-' + $now.toFormat('yyyyMMdd') + '-' + String($execution.id).padStart(4, '0');
const approval_id = 'apr_' + $execution.id;
const draft = { subject: 'Re: your HR request ' + ticket_id, body: reply };
const payload = { ticket_id, employee_id: e.employee_id, to_first_name: e.first_name, category, secondary_categories: secondary, priority, requires_hr_action: requires, hr_action_summary: summary, confidence, review_flag, request_excerpt: str(guard.clean && guard.clean.request_text, 2000), draft, ai_draft: draft, citations };
return [{ json: {
  ticket_id, approval_id, employee_id: e.employee_id, category, priority, status,
  request_text: str(guard.clean && guard.clean.request_text, 2000),
  injection_suspected: injection,
  payload_json: JSON.stringify(payload),
  checks_json: JSON.stringify({ flags, review_flag }),
  response: { ok: true, request_id: v.request_id, data: { ticket_id, status: status === 'awaiting_approval' ? 'received' : 'with_hr_team', category, message: 'Thanks ' + e.first_name + ', your request was received. HR will reply shortly.' } }
} }];
